INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter Benutzerdokumentation?', 2, '[{"text": "Anleitung für Endnutzer", "correct": true, "because": "Hilft bei Systemnutzung"}, {"text": "Technische Spezifikation", "correct": false, "because": "Für Entwickler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Benutzerdokumentation?', 3, '[{"text": "Nutzung erleichtern", "correct": true, "because": "Verständnis fördern"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Systemleistung steigern", "correct": false, "because": "Kein technisches Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer Benutzerdokumentation?', 5, '[{"text": "Bedienungsanleitung", "correct": true, "because": "Schrittweise Erklärung"}, {"text": "FAQ", "correct": true, "because": "Häufige Fragen beantworten"}, {"text": "Hardware-Spezifikationen", "correct": false, "because": "Technische Details"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Benutzerdokumentation soll verständlich sein. b) Sie ist nur für Entwickler gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Für Endnutzer, nicht Entwickler"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung einer Benutzerdokumentation?', 4, '[{"text": "Nutzerfreundlichkeit", "correct": false, "because": "Kern der Dokumentation"}, {"text": "Klare Sprache", "correct": false, "because": "Verständnis wichtig"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Benutzerdokumentation Beispiele enthalten sollte?', 2, '[{"text": "Ja", "correct": true, "because": "Erleichtert Verständnis"}, {"text": "Nein", "correct": false, "because": "Häufig enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format ist für eine Benutzerdokumentation üblich?', 3, '[{"text": "Handbuch", "correct": true, "because": "Strukturierte Anleitung"}, {"text": "Technisches Datenblatt", "correct": false, "because": "Für Entwickler"}, {"text": "Marketingbroschüre", "correct": false, "because": "Werbung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Erstellung einer Benutzerdokumentation?', 5, '[{"text": "Schritt-für-Schritt-Anleitungen", "correct": true, "because": "Nutzer führen"}, {"text": "Screenshots", "correct": true, "because": "Visuelle Unterstützung"}, {"text": "Programmiercode", "correct": false, "because": "Für Entwickler"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Eine Benutzerdokumentation hilft bei der Fehlerbehebung. b) Sie ist nur für Software nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Hardware betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Benutzerdokumentation unwichtig?', 4, '[{"text": "Verständlichkeit", "correct": false, "because": "Kernziel"}, {"text": "Struktur", "correct": false, "because": "Übersichtlichkeit"}, {"text": "Farbe der Büromöbel", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss eine Benutzerdokumentation aktuell sein?', 2, '[{"text": "Ja", "correct": true, "because": "Änderungen berücksichtigen"}, {"text": "Nein", "correct": false, "because": "Aktualität nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Benutzerdokumentation?', 4, '[{"text": "Weniger Supportanfragen", "correct": true, "because": "Nutzer selbstständig"}, {"text": "Bessere Nutzererfahrung", "correct": true, "because": "Einfachere Bedienung"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Benutzerdokumentation nur für Anfänger ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Experten"}, {"text": "Ja", "correct": false, "because": "Breiter Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Benutzerdokumentation?', 3, '[{"text": "Klarheit", "correct": true, "because": "Verständnis fördern"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Benutzerdokumentation kann digital sein. b) Sie ist nur für Hardware nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für Software"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine schlechte Benutzerdokumentation?', 5, '[{"text": "Mehr Supportaufwand", "correct": true, "because": "Nutzer verwirrt"}, {"text": "Geringe Nutzerzufriedenheit", "correct": true, "because": "Schwierige Bedienung"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei der Benutzerdokumentation?', 3, '[{"text": "Erstellung und Pflege", "correct": true, "because": "Dokumentation sicherstellen"}, {"text": "Hardwarewartung", "correct": false, "because": "Kein direkter Bezug"}, {"text": "Marketing", "correct": false, "because": "Andere Aufgabe"}]'),
